function parseMetrics(stdout) {
  const obj = {};
  (stdout || '').split('\n').forEach(l => {
    const [k, ...v] = l.split('=');
    if (k && v.length) obj[k.toLowerCase()] = v.join('=').trim();
  });
  return obj;
}

const vps1 = parseMetrics($('📊 Termômetro VPS1').first().json.stdout);
const vps2 = parseMetrics($('📊 Termômetro VPS2').first().json.stdout);

const alertas = [];
if (parseFloat(vps1.cpu_percent) > 80) alertas.push('VPS1 CPU alta: ' + vps1.cpu_percent + '%');
if (parseFloat(vps2.cpu_percent) > 80) alertas.push('VPS2 CPU alta: ' + vps2.cpu_percent + '%');
if (parseInt(vps1.mem_percent) > 90) alertas.push('VPS1 RAM critica: ' + vps1.mem_percent);
if (parseInt(vps2.mem_percent) > 90) alertas.push('VPS2 RAM critica: ' + vps2.mem_percent);

return [{ json: {
  success: true,
  timestamp: new Date().toISOString(),
  vps1,
  vps2,
  alertas,
  status: alertas.length > 0 ? 'ATENCAO' : 'SAUDAVEL'
} }];
